<?php
declare(strict_types=1);
require_once __DIR__.'/../config/bootstrap.php';require_once __DIR__.'/../config/discovery.php';
$user=require_login($pdo);$userId=(int)$user['id'];$pageTitle='Gespeicherte Suchen';$error='';$selected=null;
$identifier=static function(mixed $raw):?int{if($raw===null||$raw==='')return null;if(!is_string($raw)&&!is_int($raw))abort_request(404,'Suche nicht gefunden.');$id=filter_var($raw,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$id)abort_request(404,'Suche nicht gefunden.');return(int)$id;};
