if($selectedId!==null){try{$selected=discovery_owner_query($pdo,'search',$selectedId,$userId);$criteria=json_decode($selected['criteria_json'],true,16,JSON_THROW_ON_ERROR);if(!is_array($criteria))throw new JsonException();foreach($values as $key=>$_)if(isset($criteria[$key])&&is_string($criteria[$key]))$values[$key]=$criteria[$key];$values['name']=$selected['name'];$values['notify_mode']=$selected['notify_mode'];}catch(DomainException){abort_request(404,'Suche nicht gefunden.');}catch(JsonException){$error='Die gespeicherten Kriterien sind beschädigt. Bitte neu eingeben und speichern.';}}
elseif(($_SERVER['REQUEST_METHOD']??'GET')==='GET'){try{foreach($values as $key=>$_)if(isset($_GET[$key]))$values[$key]=discovery_text($_GET,$key,$key==='q'?200:100);}catch(InvalidArgumentException){abort_request(400,'Ungültige Suchwerte.');}}
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 require_csrf();try{$action=discovery_text($_POST,'action',16,'save');$id=$identifier($_POST['id']??null);if($action==='save'){foreach($values as $key=>$_)$values[$key]=discovery_text($_POST,$key,$key==='q'?200:100);$saved=discovery_save_search($pdo,$userId,$_POST,$id);try{discovery_scan_query($pdo,'search',$saved,50);}catch(Throwable){error_log('Initial saved-search backfill deferred.');}redirect('/user/saved-searches.php?id='.$saved.'&saved=1');}if($id===null)throw new InvalidArgumentException('Ein Suchauftrag fehlt.');discovery_transition($pdo,'search',$id,$userId,$action);redirect('/user/saved-searches.php?id='.$id);}catch(InvalidArgumentException|DomainException $exception){http_response_code(422);$error=$exception->getMessage();}}
$page=filter_var($_GET['page']??'1',FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>1000]])?:1;$q=$pdo->prepare('SELECT COUNT(*) FROM market_saved_searches WHERE user_id=?');$q->execute([$userId]);$total=(int)$q->fetchColumn();$page=min($page,max(1,(int)ceil($total/20)));
$q=$pdo->prepare('SELECT id,name,status,notify_mode FROM market_saved_searches WHERE user_id=? ORDER BY id DESC LIMIT 20 OFFSET '.(($page-1)*20));$q->execute([$userId]);$owned=$q->fetchAll();
$matchPage=filter_var($_GET['match_page']??'1',FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>21]])?:1;$matches=$selected?discovery_matches($pdo,'search',$selectedId,$userId,(int)$matchPage):[];
$countries=geo_countries();$categories=catalog_categories($pdo,true);$label=static fn(string $value):string=>function_exists('t')?t($value):$value;$states=['active'=>'Aktiv','paused'=>'Pausiert','archived'=>'Archiviert','review'=>'Suchkriterien prüfen'];$modes=['instant'=>'Sofort','daily'=>'Tägliche Zusammenfassung','off'=>'Aus'];
include __DIR__.'/../includes/header.php';?>
