<?php if(!$selected||$selected['status']!=='archived'):?><section class="panel"><h2><?=h($label($selected?'Suche bearbeiten':'Suche speichern'))?></h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$selectedId??''?>">
