<label class="field"><?=h($label('Bezugsland für die Entfernung'))?><select name="origin_country"><?php foreach($countries as $code=>$name):?><option value="<?=h($code)?>" <?=$values['origin_country']===$code?'selected':''?>><?=h($name)?></option><?php endforeach;?></select></label><label class="field"><?=h($label('Bezugs-Postleitzahl'))?><input name="zip" maxlength="16" value="<?=h($values['zip'])?>"></label><label class="field"><?=h($label('Radius in km'))?><input name="radius_km" type="number" min="1" max="2000" value="<?=h($values['radius_km'])?>"></label>
<label class="field"><?=h($label('Sortierung'))?><select name="sort"><?php foreach(['newest'=>'Neueste zuerst','price_asc'=>'Preis aufsteigend','price_desc'=>'Preis absteigend','ending'=>'Bald endend','distance'=>'Nächste zuerst'] as $value=>$name):?><option value="<?=h($value)?>" <?=$values['sort']===$value?'selected':''?>><?=h($label($name))?></option><?php endforeach;?></select></label>
<label class="field"><?=h($label('Suchalarm'))?><select name="notify_mode"><?php foreach($modes as $value=>$name):?><option value="<?=h($value)?>" <?=$values['notify_mode']===$value?'selected':''?>><?=h($label($name))?></option><?php endforeach;?></select></label><p><?=h($label('Die globalen Benachrichtigungseinstellungen haben Vorrang. Tägliche Zusammenfassungen bündeln neue Treffer des Vortages.'))?></p><button type="submit" class="button"><?=h($label('Suche speichern'))?></button></form></section><?php endif;?>
