<section class="panel"><h2><?=h($label('Meine gespeicherten Suchen'))?></h2><?php if(!$owned):?><p><?=h($label('Noch keine gespeicherten Suchen.'))?></p><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th><?=h($label('Suche'))?></th><th><?=h($label('Status'))?></th><th><?=h($label('Suchalarm'))?></th><th><?=h($label('Aktionen'))?></th></tr></thead><tbody><?php foreach($owned as $search):?><tr><td><a href="?id=<?=(int)$search['id']?>"><?=h($search['name'])?></a></td><td><?=h($label($states[$search['status']]??'In Bearbeitung'))?></td><td><?=h($label($modes[$search['notify_mode']]??'Aus'))?></td><td><?php if($search['status']!=='archived'):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$search['id']?>"><select name="action" aria-label="Suchaktion"><option value="<?=$search['status']==='active'?'pause':'resume'?>"><?=h($label($search['status']==='active'?'Pausieren':'Aktivieren'))?></option><option value="archive"><?=h($label('Archivieren'))?></option></select><button class="button secondary"><?=h($label('Ausführen'))?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><nav class="pagination"><?php if($page>1):?><a href="?page=<?=$page-1?>"><?=h($label('Zurück'))?></a><?php endif;?><span><?=h($label('Seite'))?> <?=$page?> / <?=max(1,(int)ceil($total/20))?></span><?php if($page*20<$total):?><a href="?page=<?=$page+1?>"><?=h($label('Weiter'))?></a><?php endif;?></nav></section></main>
